use super::*;
use semio_s_artifact_procedural_3d_geometry_compute::original::tests::accounted;
use semio_s_artifact_procedural_3d_geometry_compute::original::tests::close;
use semio_s_artifact_procedural_3d_geometry_compute::original::tests::grant;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_artifact_flow_flow::neural::{Atom,Dictionary,Value as NeuralValue};
use semio_s_artifact_procedural_3d_io_geometry::NativeGeometryComputeContext;
use semio_s_artifact_procedural_3d_io_text::snapshot::catalogue::catalogue;
use semio_framework_value::retained_clone::RetainedCloneGrant;
fn clock()->Option<u64>{Some(1)}
fn atom(text:&str)->NeuralValue{NeuralValue::Atom(Atom::String(text.into()))}
fn scalar(value:&serde_json::Value)->NeuralValue{if let Some(flag)=value.as_bool(){NeuralValue::Dictionary(Dictionary::new().insert("$schema",atom("boolean")).insert("value",NeuralValue::Atom(Atom::Boolean(flag))))}else{NeuralValue::Dictionary(Dictionary::new().insert("$schema",atom("number")).insert("value",NeuralValue::Atom(Atom::Decimal(value.as_f64().unwrap()))))}}
fn literal_value(port:&str,value:&serde_json::Value)->NeuralValue{
 if port=="plane"{return NeuralValue::Dictionary(Dictionary::new().insert("$schema",atom("plane")).insert("origin",literal_value("origin",&value["origin"])).insert("normal",literal_value("normal",&value["normal"])))}
 if let Some(items)=value.as_array(){if matches!(port,"vertex"|"edge"|"face"){return NeuralValue::Dictionary(items.iter().enumerate().fold(Dictionary::new().insert("$schema",atom("list")),|dictionary,(i,v)|dictionary.insert(i.to_string(),scalar(v))))}return NeuralValue::Dictionary(Dictionary::new().insert("$schema",atom(if matches!(port,"offset"|"normal"|"axis"|"factor"){"vector"}else{"point"})).insert("x",NeuralValue::Atom(Atom::Decimal(items[0].as_f64().unwrap()))).insert("y",NeuralValue::Atom(Atom::Decimal(items[1].as_f64().unwrap()))).insert("z",NeuralValue::Atom(Atom::Decimal(items[2].as_f64().unwrap()))))}scalar(value)
}
fn snapshot(law:&serde_json::Value)->Generation3dSnapshot{
 let mut snapshot=Generation3dSnapshot::default();
 snapshot.host_snapshot.widgets=law["widgets"].as_array().unwrap().iter().map(|row|{let id=row["id"].as_str().unwrap().to_string();let kind=row["kind"].as_str().unwrap();if kind=="input-slider"{return Widget::InputSlider{id,label:"Width".into(),value:row["params"]["value"].as_f64().unwrap(),min:0.0,max:100.0,step:0.1}}let params=row["params"].as_object().unwrap().iter().fold(Dictionary::new(),|dictionary,(port,value)|dictionary.insert(port.clone(),literal_value(port,value)));Widget::Neuron{id,neuron_kind:kind.into(),params,input_ports:Vec::new(),output_ports:Vec::new(),preview:true}}).collect();
 snapshot.host_snapshot.synapses=law["wires"].as_array().unwrap().iter().enumerate().map(|(i,row)|SynapseSpec{id:i.to_string(),from:row["from"].as_str().unwrap().into(),from_port:row["fromPort"].as_str().unwrap().into(),to:row["to"].as_str().unwrap().into(),to_port:row["toPort"].as_str().unwrap().into()}).collect();snapshot
}
fn key(widget:&Widget)->&String{match widget{Widget::Neuron{id,..}|Widget::InputSlider{id,..}=>id,_=>unreachable!()}}
fn field(input:&GeometryInput<'_>,key:&String,parents:&[Arc<WidgetEvaluation>],pending:&mut Option<Box<dyn InferencePending>>,cx:&mut StepContext<'_>)->Result<ComputeStep<Arc<WidgetEvaluation>>,OriginalTurnFailure>{Generation3dGeometry::compute_step(input,key,parents,pending,cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("original field returned a flattened refusal")})}
fn close_pending(pending:&mut Option<Box<dyn InferencePending>>,caller:&mut OriginalJobFixtureCaller,stock:RetainedCloneGrant,born:&mut usize,released:&mut usize){
 for _ in 0..100000{if pending.is_none(){break}accounted(caller,stock,born,released,|cx|{let owner=pending.as_mut().unwrap();if !owner.close_original(cx)?||cx.should_yield(){return Ok(())}let bytes=owner.original_box_release_bytes().unwrap();let grant=cx.retained_grant();if grant.maximum_release_bytes<bytes||grant.maximum_items==0||grant.maximum_depth==0{return Ok(())}post(cx,RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()})?;pending.take();Ok(())});}assert!(pending.is_none());
}

#[test]
fn original_geometry_inferred_field_resolves_real_graph_and_closes_every_dynamic_owner(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️.json")).unwrap();let c=&law["originalCaller"];let stock=grant(c);let mut caller=OriginalJobFixtureCaller::admit(OperationId(c["operation"].as_u64().unwrap()),Generation(c["generation"].as_u64().unwrap()),stock,clock,c["deadlineMicros"].as_u64().unwrap(),c["fuel"].as_u64().unwrap());let(snapshot,source_heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||snapshot(&law));let original=source_heap.requested_bytes-source_heap.released_bytes;let catalogue=catalogue();let input=GeometryInput::new(&snapshot,catalogue,&NativeGeometryComputeContext);let mut born=0;let mut released=0;let mut outputs:[Option<Arc<WidgetEvaluation>>;9]=std::array::from_fn(|_|None);
 for i in 0..9{
  let key=key(&snapshot.host_snapshot.widgets[i]);let(previous,current)=outputs.split_at_mut(i);let parents=match i{1=>previous[0].as_slice(),3=>previous[2].as_slice(),4|7=>previous[1].as_slice(),8=>previous[7].as_slice(),_=>&[]};let mut pending=None;
  let before=caller.cumulative_receipt();let outcome=accounted(&mut caller,Default::default(),&mut born,&mut released,|cx|field(&input,key,parents,&mut pending,cx));assert!(matches!(outcome,ComputeStep::Working{fuel_used:0,..}));assert!(pending.is_none());assert_eq!(before,caller.cumulative_receipt());let mut progress=0.0;
  for _ in 0..100000{match accounted(&mut caller,stock,&mut born,&mut released,|cx|field(&input,key,parents,&mut pending,cx)){ComputeStep::Working{progress:next,..}=>{assert!(next>=progress&&next<=1.0);progress=next},ComputeStep::Done{value,..}=>{current[0]=Some(value);break}}}
  assert!(pending.is_none());assert!(current[0].is_some());
 }
 for(i,name)in[(0,"width Ä"),(5,"number")]{let GeometryValue::Number(value)=outputs[i].as_ref().unwrap().outputs.get(if i==0{"number"}else{"value"}).unwrap()else{panic!("actual original graph number")};assert_eq!(*value,law["expected"][name].as_f64().unwrap())}
 let GeometryValue::Boolean(flag)=outputs[6].as_ref().unwrap().outputs.get("value").unwrap()else{panic!("actual original graph boolean")};assert_eq!(*flag,law["expected"]["flag"].as_bool().unwrap());
 for(i,port,name)in[(3,"point","curve point"),(4,"position","position"),(8,"position","translated position")]{let GeometryValue::Point(point)=outputs[i].as_ref().unwrap().outputs.get(port).unwrap()else{panic!("actual original graph geometry point")};for axis in 0..3{assert_eq!(point[axis],law["expected"][name][axis].as_f64().unwrap())}}
 close((snapshot,outputs),&mut caller,stock,&mut born,&mut released);assert_eq!(original+born,released);caller.retire(stock);
}

#[test]
fn original_geometry_inferred_field_keeps_actual_output_on_denied_handoff_and_cancel(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️.json")).unwrap();let c=&law["originalCaller"];let stock=grant(c);let mut caller=OriginalJobFixtureCaller::admit(OperationId(c["operation"].as_u64().unwrap()),Generation(c["generation"].as_u64().unwrap()),stock,clock,c["deadlineMicros"].as_u64().unwrap(),c["fuel"].as_u64().unwrap());let(snapshot,source_heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||snapshot(&law));let original=source_heap.requested_bytes-source_heap.released_bytes;let catalogue=catalogue();let input=GeometryInput::new(&snapshot,catalogue,&NativeGeometryComputeContext);let key=key(&snapshot.host_snapshot.widgets[5]);let mut pending=None;let mut born=0;let mut released=0;
 for _ in 0..100000{let mut result=None;accounted(&mut caller,stock,&mut born,&mut released,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{result=Some(field(&input,key,&[],&mut pending,cx)?);Ok(())}));assert!(matches!(result.unwrap(),ComputeStep::Working{..}));if pending.as_mut().and_then(|owner|owner.as_any_mut().downcast_mut::<OriginalGeometryPending>()).is_some_and(|owner|owner.output.is_some()){break}}
 let pointer=pending.as_mut().unwrap().as_any_mut().downcast_mut::<OriginalGeometryPending>().unwrap().output.as_ref().map(Arc::as_ptr).unwrap();let before=caller.cumulative_receipt();let result=accounted(&mut caller,RetainedCloneGrant{maximum_release_bytes:size_of::<OriginalGeometryPending>()-1,..stock},&mut born,&mut released,|cx|field(&input,key,&[],&mut pending,cx));assert!(matches!(result,ComputeStep::Working{..}));assert_eq!(before,caller.cumulative_receipt());assert_eq!(pending.as_mut().unwrap().as_any_mut().downcast_mut::<OriginalGeometryPending>().unwrap().output.as_ref().map(Arc::as_ptr).unwrap(),pointer);
 let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{semio_framework_async::poll::resolve_ready(caller.cancel().cancel());pending.as_mut().unwrap().cancel();});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close_pending(&mut pending,&mut caller,stock,&mut born,&mut released);close(snapshot,&mut caller,stock,&mut born,&mut released);assert_eq!(original+born,released);caller.retire(stock);
}

#[test]
fn original_geometry_engine_keeps_completed_rows_without_cloning_and_closes_snapshot_on_its_caller(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️.json")).unwrap();let c=&law["originalCaller"];let stock=grant(c);let mut caller=OriginalJobFixtureCaller::admit(OperationId(c["operation"].as_u64().unwrap()),Generation(c["generation"].as_u64().unwrap()),stock,clock,c["deadlineMicros"].as_u64().unwrap(),c["fuel"].as_u64().unwrap());
 let mut engine=super::super::engine::GeometryEngine::new(Arc::clone(catalogue()),semio_s_artifact_procedural_3d_io_geometry::context(),0);
 let(admission,source_heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||super::super::engine::EngineAdmission::new("actual graph Ä".into(),snapshot(&law),super::super::engine::CacheMode::Bypass,"same actor Ä".into()));let original=source_heap.requested_bytes-source_heap.released_bytes;let mut donor=Some(admission);let mut born=0;let mut released=0;
 let before=caller.cumulative_receipt();assert!(!accounted(&mut caller,Default::default(),&mut born,&mut released,|cx|engine.start_original_step(&mut donor,cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original admission failure")})));assert!(donor.is_some());assert_eq!(before,caller.cumulative_receipt());
 for _ in 0..100000{if accounted(&mut caller,stock,&mut born,&mut released,|cx|engine.start_original_step(&mut donor,cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original admission failure")})){break}}assert!(donor.is_none());
 for _ in 0..100000{let report=accounted(&mut caller,stock,&mut born,&mut released,|cx|engine.step(cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original driver failure")}));if report.done{break}}
 assert_eq!(engine.evaluations().count(),9);let pointer=engine.evaluation("number").map(Arc::as_ptr).unwrap();let source=key(&engine.base().unwrap().host_snapshot.widgets[5]);
 let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert_eq!(engine.evaluation("number").map(Arc::as_ptr).unwrap(),pointer);let(key,value)=engine.evaluations().find(|(key,_)|key.as_str()=="number").unwrap();assert_eq!(key.as_ptr(),source.as_ptr());assert_eq!(Arc::as_ptr(value),pointer);});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let before=caller.cumulative_receipt();assert!(!accounted(&mut caller,Default::default(),&mut born,&mut released,|cx|engine.close_original_step(cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original closure failure")})));assert_eq!(before,caller.cumulative_receipt());assert_eq!(engine.evaluation("number").map(Arc::as_ptr).unwrap(),pointer);
 for _ in 0..100000{if accounted(&mut caller,stock,&mut born,&mut released,|cx|engine.close_original_step(cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original closure failure")})){break}}assert!(engine.terminal_is_empty());assert_eq!(original+born,released);caller.retire(stock);
}

#[test]
fn original_geometry_number_policy_uses_explicit_host_and_closes_actual_inputs(){
 struct Policy{value:f64}
 impl semio_s_artifact_procedural_3d_geometry_compute::GeometryComputeContext for Policy{
  fn lookup(&self,_kind:&str)->Option<semio_s_artifact_procedural_3d_geometry_compute::StartFn>{None}
  fn start_original(&self,kind:&Kind,inputs:&mut Option<WidgetInputs>,cx:&mut StepContext<'_>)->Result<Option<OriginalFixedOutputJob>,OriginalTurnFailure>{OriginalFixedOutputJob::admit_number(kind,inputs,self.value,cx)}
 }
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️.json")).unwrap();let c=&law["originalCaller"];let policy=Policy{value:law["hostPolicy"]["value"].as_f64().unwrap()};let stock=grant(c);let mut caller=OriginalJobFixtureCaller::admit(OperationId(c["operation"].as_u64().unwrap()),Generation(c["generation"].as_u64().unwrap()),stock,clock,c["deadlineMicros"].as_u64().unwrap(),c["fuel"].as_u64().unwrap());let(snapshot,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||snapshot(&law));let original=heap.requested_bytes-heap.released_bytes;let input=GeometryInput::new(&snapshot,catalogue(),&policy);let key=key(&snapshot.host_snapshot.widgets[5]);let mut pending=None;let mut output=None;let mut born=0;let mut released=0;
 for _ in 0..100000{let mut result=None;accounted(&mut caller,stock,&mut born,&mut released,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{result=Some(field(&input,key,&[],&mut pending,cx)?);Ok(())}));if let ComputeStep::Done{value,..}=result.unwrap(){output=Some(value);break}}
 assert!(pending.is_none());let output=output.unwrap();assert_eq!(output.outputs.get("value"),Some(&GeometryValue::Number(policy.value)));close((snapshot,output),&mut caller,stock,&mut born,&mut released);assert_eq!(original+born,released);caller.retire(stock);
}

#[test]
fn original_geometry_cyclic_plan_publishes_real_localized_faults_on_same_caller(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔄️cycle/🧫️.json")).unwrap();let caller_law:serde_json::Value=serde_json::from_str(include_str!("🧫️.json")).unwrap();let c=&caller_law["originalCaller"];let stock=grant(c);let mut caller=OriginalJobFixtureCaller::admit(OperationId(c["operation"].as_u64().unwrap()),Generation(c["generation"].as_u64().unwrap()),stock,clock,c["deadlineMicros"].as_u64().unwrap(),c["fuel"].as_u64().unwrap());
 let mut engine=super::super::engine::GeometryEngine::new(Arc::clone(catalogue()),semio_s_artifact_procedural_3d_io_geometry::context(),0);
 let(admission,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||super::super::engine::EngineAdmission::new("real cycle Ä".into(),snapshot(&law),super::super::engine::CacheMode::Bypass,"original cycle caller".into()));let original=heap.requested_bytes-heap.released_bytes;let mut donor=Some(admission);let mut born=0;let mut released=0;
 for _ in 0..100000{if accounted(&mut caller,stock,&mut born,&mut released,|cx|engine.start_original_step(&mut donor,cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original cyclic admission failure")})){break}}assert!(donor.is_none());let mut done=false;let mut progress=0.0;
 for _ in 0..100000{let report=accounted(&mut caller,stock,&mut born,&mut released,|cx|engine.step(cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original cyclic driver failure")}));assert!(report.fraction>=progress);progress=report.fraction;if report.done{done=true;break}}assert!(done);assert_eq!(engine.evaluations().count(),3);
 for row in law["faultRows"].as_array().unwrap(){let evaluation=engine.evaluation(row["id"].as_str().unwrap()).unwrap();assert!(evaluation.outputs.is_empty());let fault=evaluation.fault.as_ref().unwrap();assert_eq!(fault.code,row["code"].as_str().unwrap());assert_eq!(fault.message.en,row["en"].as_str().unwrap());assert_eq!(fault.message.de,row["de"].as_str().unwrap());assert!(fault.port.is_none());}
 for _ in 0..100000{if accounted(&mut caller,stock,&mut born,&mut released,|cx|engine.close_original_step(cx).map_err(|failure|match failure{InferenceWorkFailure::Original(original)=>original,_=>panic!("full original cyclic closure failure")})){break}}assert!(engine.terminal_is_empty());assert_eq!(original+born,released);caller.retire(stock);
}

