 for _ in 0..10000{if lookup.comparison_pending(){let before=caller.cumulative_receipt();assert!(!accounted(&mut caller,RetainedCloneGrant{maximum_copy_bytes:0,..stock},&mut born,&mut released,|cx|{let(done,receipt)=lookup.step(&dictionary,needle,cx.retained_grant())?;assert_eq!(receipt,Default::default());Ok(done)}));assert_eq!(before,caller.cumulative_receipt());denied=true;}if accounted(&mut caller,stock,&mut born,&mut released,|cx|{let(done,receipt)=lookup.step(&dictionary,needle,cx.retained_grant()).map_err(|error|OriginalTurnFailure::debit_original(error,cx))?;if receipt!=Default::default(){post(cx,receipt)?}Ok(done)}){break}}
 assert!(denied);let value=lookup.result(&dictionary).unwrap().unwrap();assert_eq!(value.as_atom().unwrap(),&Atom::Integer(law["expected"].as_i64().unwrap()));let native=dictionary.iter().find(|(key,_)|key.as_str()==needle).unwrap().1;assert!(std::ptr::eq(value,native));assert_eq!((born,released),(0,0));close((lookup,dictionary),&mut caller,stock,&mut born,&mut released);assert_eq!(original+born,released);caller.retire(stock);
